B.abN=new A.t([B.m,"Mazzo modificato su un altro dispositivo. Le modifiche locali non sono sincronizzate.",B.l,"Mazo modificado en otro dispositivo. Los cambios locales no est\xe1n sincronizados.",B.j,"\u5225\u306e\u7aef\u672b\u3067\u30c7\u30c3\u30ad\u304c\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\u3002\u30ed\u30fc\u30ab\u30eb\u306e\u5909\u66f4\u306f\u672a\u540c\u671f\u3067\u3059\u3002",B.i,"\ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \ub371\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub85c\uceec \ubcc0\uacbd \uc0ac\ud56d\uc740 \ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.",B.h,"\u724c\u7ec4\u5df2\u5728\u53e6\u4e00\u53f0\u8bbe\u5907\u4e0a\u66f4\u6539\u3002\u672c\u5730\u66f4\u6539\u5c1a\u672a\u540c\u6b65\u3002",B.k,"Deck auf einem anderen Ger\xe4t ge\xe4ndert. Lokale \xc4nderungen sind nicht synchronisiert."],t.N)
B.aaJ=new A.t([B.m,"Mazzo salvato solo in locale. Sincronizzazione cloud non riuscita.",B.l,"Mazo guardado solo localmente. Fall\xf3 la sincronizaci\xf3n.",B.j,"\u30c7\u30c3\u30ad\u306f\u7aef\u672b\u306b\u4fdd\u5b58\u3055\u308c\u307e\u3057\u305f\u3002\u30af\u30e9\u30a6\u30c9\u540c\u671f\u306b\u5931\u6557\u3057\u307e\u3057\u305f\u3002",B.i,"\ub371\uc774 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ud074\ub77c\uc6b0\ub4dc \ub3d9\uae30\ud654\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4.",B.h,"\u724c\u7ec4\u4ec5\u4fdd\u5b58\u5728\u672c\u5730\u3002\u4e91\u540c\u6b65\u5931\u8d25\u3002",B.k,"Deck nur lokal gespeichert. Cloud-Synchronisierung fehlgeschlagen."],t.N)
B.adq=new A.t([B.m,"Mazzo cloud non disponibile. Le modifiche su questo dispositivo non sono sincronizzate.",B.l,"Mazo en la nube no disponible. Los cambios de este dispositivo no est\xe1n sincronizados.",B.j,"\u30af\u30e9\u30a6\u30c9\u306e\u30c7\u30c3\u30ad\u3092\u53d6\u5f97\u3067\u304d\u307e\u305b\u3093\u3002\u3053\u306e\u7aef\u672b\u306e\u5909\u66f4\u306f\u672a\u540c\u671f\u3067\u3059\u3002",B.i,"\ud074\ub77c\uc6b0\ub4dc \ub371\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774 \uae30\uae30\uc758 \ubcc0\uacbd \uc0ac\ud56d\uc740 \ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.",B.h,"\u4e91\u7aef\u724c\u7ec4\u4e0d\u53ef\u7528\u3002\u6b64\u8bbe\u5907\u4e0a\u7684\u66f4\u6539\u5c1a\u672a\u540c\u6b65\u3002",B.k,"Cloud-Deck nicht verf\xfcgbar. \xc4nderungen auf diesem Ger\xe4t sind nicht synchronisiert."],t.N)
B.abC=new A.t([B.m,"3\u201316 caratteri, senza spazi. Vietati nomi riservati o offensivi.",B.l,"3\u201316 caracteres, sin espacios ni nombres reservados u ofensivos.",B.j,"3\uff5e16\u6587\u5b57\u3001\u30b9\u30da\u30fc\u30b9\u4e0d\u53ef\u3002\u4e88\u7d04\u8a9e\u3084\u4e0d\u9069\u5207\u306a\u540d\u524d\u306f\u7981\u6b62\u3002",B.i,"3~16\uc790, \uacf5\ubc31 \ubd88\uac00. \uc608\uc57d\uc5b4\uc640 \ubd80\uc801\uc808\ud55c \uc774\ub984\uc740 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.",B.h,"3\u201316\u4e2a\u5b57\u7b26\uff0c\u4e0d\u53ef\u5305\u542b\u7a7a\u683c\u3001\u4fdd\u7559\u8bcd\u6216\u5192\u72af\u6027\u8bcd\u8bed\u3002",B.k,"3\u201316 Zeichen, keine Leerzeichen, reservierten oder beleidigenden Namen."],t.N)
B.ady=new A.t([B.m,"Il nome deve avere 3\u201316 caratteri, senza spazi o parole inappropriate.",B.l,"El nombre debe tener de 3 a 16 caracteres, sin espacios ni palabras ofensivas.",B.j,"\u540d\u524d\u306f3\uff5e16\u6587\u5b57\u3067\u3001\u7a7a\u767d\u3084\u4e0d\u9069\u5207\u306a\u8a9e\u53e5\u306f\u4f7f\u7528\u3067\u304d\u307e\u305b\u3093\u3002",B.i,"\uc774\ub984\uc740 3~16\uc790\uc5ec\uc57c \ud558\uba70 \uacf5\ubc31\uc774\ub098 \ubd80\uc801\uc808\ud55c \ub2e8\uc5b4\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.",B.h,"\u540d\u79f0\u987b\u4e3a3\u201316\u4e2a\u5b57\u7b26\uff0c\u4e0d\u5f97\u542b\u7a7a\u683c\u6216\u4e0d\u5f53\u8bcd\u8bed\u3002",B.k,"Der Name muss 3\u201316 Zeichen lang sein, ohne Leerzeichen oder unangemessene W\xf6rter."],t.N)
