B.abf=new A.t([B.m,"2 cariche gratis; ciascuna si ricarica 12 ore dopo l\u2019uso.",B.l,"2 cargas gratis; cada una se recarga 12 horas despu\xe9s de usarla.",B.j,"\u7121\u6599\u30c1\u30e3\u30fc\u30b8\u306f2\u56de\u5206\u3002\u4f7f\u7528\u5f8c12\u6642\u9593\u3067\u54041\u56de\u5fa9\u3057\u307e\u3059\u3002",B.i,"\ubb34\ub8cc \ucda9\uc804 2\ud68c; \uc0ac\uc6a9 \ud6c4 \uac01\uac01 12\uc2dc\uac04 \ub4a4 \ucda9\uc804\ub429\ub2c8\ub2e4.",B.h,"2\u6b21\u514d\u8d39\u5145\u80fd\uff1b\u6bcf\u6b21\u4f7f\u7528\u540e12\u5c0f\u65f6\u6062\u590d\u3002",B.k,"2 Gratisladungen; jede l\xe4dt sich 12 Stunden nach Nutzung auf."],t.N)
B.adG=new A.t([B.m,"Tutti i 9 eroi: 11,11% ciascuno.",B.l,"Los 9 h\xe9roes: 11,11% cada uno.",B.j,"9\u4eba\u306e\u82f1\u96c4\uff1a\u540411.11%\u3002",B.i,"\uc601\uc6c5 9\uba85: \uac01\uac01 11.11%.",B.h,"\u4e5d\u4f4d\u82f1\u96c4\uff1a\u6bcf\u4f4d11.11%\u3002",B.k,"Alle 9 Helden: je 11,11 %."],t.N)
B.aca=new A.t([B.m,"Costo: 600 Shard. Dren ha probabilit\xe0 aumentata.",B.l,"Coste: 600 Shards. Dren tiene probabilidad aumentada.",B.j,"\u30b3\u30b9\u30c8\uff1a600\u30b7\u30e3\u30fc\u30c9\u3002\u30c9\u30ec\u30f3\u51fa\u73fe\u7387\u30a2\u30c3\u30d7\u3002",B.i,"\ube44\uc6a9: \uc0e4\ub4dc 600\uac1c. \ub4dc\ub80c \ud655\ub960 \uc99d\uac00.",B.h,"\u82b1\u8d39\uff1a600\u788e\u7247\u3002\u5fb7\u4f26\u6982\u7387\u63d0\u5347\u3002",B.k,"Kosten: 600 Shards. Erh\xf6hte Dren-Chance."],t.N)
B.abp=new A.t([B.m,"Nessun evento attivo. Probabilit\xe0 e costo non sono ancora definiti.",B.l,"No hay ning\xfan evento activo. A\xfan no hay probabilidades ni coste definidos.",B.j,"\u958b\u50ac\u4e2d\u306e\u30a4\u30d9\u30f3\u30c8\u306f\u3042\u308a\u307e\u305b\u3093\u3002\u78ba\u7387\u3068\u30b3\u30b9\u30c8\u306f\u672a\u8a2d\u5b9a\u3067\u3059\u3002",B.i,"\uc9c4\ud589 \uc911\uc778 \uc774\ubca4\ud2b8\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \ud655\ub960\uacfc \ube44\uc6a9\uc774 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.",B.h,"\u5f53\u524d\u6ca1\u6709\u6d3b\u52a8\u3002\u6d3b\u52a8\u6982\u7387\u548c\u82b1\u8d39\u5c1a\u672a\u8bbe\u5b9a\u3002",B.k,"Kein Event aktiv. Raten und Kosten sind noch nicht festgelegt."],t.N)
B.adE=new A.t([B.m,"ATK: 1\u2013100 \xb7 CRIT: 0\u201325% \xb7 1 skill per carta.",B.l,"ATK: 1\u2013100 \xb7 CRIT: 0\u201325% \xb7 1 habilidad por carta.",B.j,"ATK\uff1a1\uff5e100 \xb7 CRIT\uff1a0\uff5e25% \xb7 \u30ab\u30fc\u30c9\u3054\u3068\u306b\u30b9\u30ad\u30eb1\u500b\u3002",B.i,"ATK: 1\u2013100 \xb7 CRIT: 0\u201325% \xb7 \uce74\ub4dc\ub2f9 \uc2a4\ud0ac 1\uac1c.",B.h,"ATK\uff1a1\u2013100 \xb7 CRIT\uff1a0\u201325% \xb7 \u6bcf\u5f20\u53611\u4e2a\u6280\u80fd\u3002",B.k,"ATK: 1\u2013100 \xb7 CRIT: 0\u201325 % \xb7 1 F\xe4higkeit pro Karte."],t.N)
B.abn=new A.t([B.m,"Duplicato: mantieni le nuove statistiche o prendi 100 Shard.",B.l,"Duplicado: conserva las nuevas estad\xedsticas o recibe 100 Shards.",B.j,"\u91cd\u8907\uff1a\u65b0\u3057\u3044\u80fd\u529b\u5024\u3092\u4fdd\u6301\u3059\u308b\u304b100\u30b7\u30e3\u30fc\u30c9\u3092\u7372\u5f97\u3002",B.i,"\uc911\ubcf5: \uc0c8 \ub2a5\ub825\uce58\ub97c \uc720\uc9c0\ud558\uac70\ub098 \uc0e4\ub4dc 100\uac1c\ub97c \ubc1b\uc73c\uc138\uc694.",B.h,"\u91cd\u590d\u5361\uff1a\u4fdd\u7559\u65b0\u5c5e\u6027\u6216\u83b7\u5f97100\u788e\u7247\u3002",B.k,"Duplikat: Neue Werte behalten oder 100 Shards nehmen."],t.N)
B.abK=new A.t([B.m,"Salvataggio locale",B.l,"Partida local",B.j,"\u30ed\u30fc\u30ab\u30eb\u30bb\u30fc\u30d6",B.i,"\ub85c\uceec \uc800\uc7a5",B.h,"\u672c\u5730\u5b58\u6863",B.k,"Lokaler Spielstand"],t.N)
B.aaY=new A.t([B.m,"Salvataggio locale \xb7 accedi per attivare il backup cloud",B.l,"Partida local \xb7 inicia sesi\xf3n para activar la copia en la nube",B.j,"\u30ed\u30fc\u30ab\u30eb\u30bb\u30fc\u30d6 \xb7 \u30ed\u30b0\u30a4\u30f3\u3057\u3066\u30af\u30e9\u30a6\u30c9\u30d0\u30c3\u30af\u30a2\u30c3\u30d7\u3092\u6709\u52b9\u5316",B.i,"\ub85c\uceec \uc800\uc7a5 \xb7 \ub85c\uadf8\uc778\ud558\uc5ec \ud074\ub77c\uc6b0\ub4dc \ubc31\uc5c5 \ud65c\uc131\ud654",B.h,"\u672c\u5730\u5b58\u6863 \xb7 \u767b\u5f55\u4ee5\u542f\u7528\u4e91\u7aef\u5907\u4efd",B.k,"Lokaler Spielstand \xb7 anmelden f\xfcr Cloud-Backup"],t.N)
B.aao=new A.t([B.m,"Controllo salvataggio cloud\u2026",B.l,"Comprobando partida en la nube\u2026",B.j,"\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u3092\u78ba\u8a8d\u4e2d\u2026",B.i,"\ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5 \ud655\uc778 \uc911\u2026",B.h,"\u6b63\u5728\u68c0\u67e5\u4e91\u7aef\u5b58\u6863\u2026",B.k,"Cloud-Spielstand wird gepr\xfcft\u2026"],t.N)
B.abm=new A.t([B.m,"Connessione a Firebase\u2026",B.l,"Contactando con Firebase\u2026",B.j,"Firebase\u306b\u63a5\u7d9a\u4e2d\u2026",B.i,"Firebase \uc5f0\uacb0 \uc911\u2026",B.h,"\u6b63\u5728\u8fde\u63a5 Firebase\u2026",B.k,"Firebase wird kontaktiert\u2026"],t.N)
B.acn=new A.t([B.m,"Autenticazione completata. Caricamento account\u2026",B.l,"Autenticaci\xf3n completada. Cargando cuenta\u2026",B.j,"\u8a8d\u8a3c\u5b8c\u4e86\u3002\u30a2\u30ab\u30a6\u30f3\u30c8\u3092\u8aad\u307f\u8fbc\u307f\u4e2d\u2026",B.i,"\uc778\uc99d \uc644\ub8cc. \uacc4\uc815 \ubd88\ub7ec\uc624\ub294 \uc911\u2026",B.h,"\u8eab\u4efd\u9a8c\u8bc1\u5b8c\u6210\u3002\u6b63\u5728\u52a0\u8f7d\u8d26\u6237\u2026",B.k,"Authentifizierung abgeschlossen. Konto wird geladen\u2026"],t.N)
B.abc=new A.t([B.m,"Autenticazione fallita. Controlla i dati e riprova.",B.l,"Error de autenticaci\xf3n. Comprueba tus datos e int\xe9ntalo de nuevo.",B.j,"\u8a8d\u8a3c\u306b\u5931\u6557\u3057\u307e\u3057\u305f\u3002\u5165\u529b\u5185\u5bb9\u3092\u78ba\u8a8d\u3057\u3066\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\uc778\uc99d\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4. \uc815\ubcf4\ub97c \ud655\uc778\ud558\uace0 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.",B.h,"\u8eab\u4efd\u9a8c\u8bc1\u5931\u8d25\u3002\u8bf7\u68c0\u67e5\u4fe1\u606f\u5e76\u91cd\u8bd5\u3002",B.k,"Authentifizierung fehlgeschlagen. Angaben pr\xfcfen und erneut versuchen."],t.N)
B.aaD=new A.t([B.m,"Email per il reset della password inviata.",B.l,"Correo para restablecer la contrase\xf1a enviado.",B.j,"\u30d1\u30b9\u30ef\u30fc\u30c9\u518d\u8a2d\u5b9a\u30e1\u30fc\u30eb\u3092\u9001\u4fe1\u3057\u307e\u3057\u305f\u3002",B.i,"\ube44\ubc00\ubc88\ud638 \uc7ac\uc124\uc815 \uc774\uba54\uc77c\uc744 \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4.",B.h,"\u5bc6\u7801\u91cd\u7f6e\u90ae\u4ef6\u5df2\u53d1\u9001\u3002",B.k,"E-Mail zum Zur\xfccksetzen des Passworts gesendet."],t.N)
B.adJ=new A.t([B.m,"Cloud non disponibile. I progressi locali sono al sicuro.",B.l,"Nube no disponible. El progreso local est\xe1 seguro.",B.j,"\u30af\u30e9\u30a6\u30c9\u3092\u5229\u7528\u3067\u304d\u307e\u305b\u3093\u3002\u30ed\u30fc\u30ab\u30eb\u306e\u9032\u884c\u72b6\u6cc1\u306f\u5b89\u5168\u3067\u3059\u3002",B.i,"\ud074\ub77c\uc6b0\ub4dc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ub85c\uceec \uc9c4\ud589 \uc0c1\ud669\uc740 \uc548\uc804\ud569\ub2c8\ub2e4.",B.h,"\u4e91\u7aef\u4e0d\u53ef\u7528\u3002\u672c\u5730\u8fdb\u5ea6\u5b89\u5168\u65e0\u635f\u3002",B.k,"Cloud nicht verf\xfcgbar. Lokaler Fortschritt ist sicher."],t.N)
B.acQ=new A.t([B.m,"Nessun backup cloud disponibile.",B.l,"No hay copia en la nube disponible.",B.j,"\u5229\u7528\u53ef\u80fd\u306a\u30af\u30e9\u30a6\u30c9\u30d0\u30c3\u30af\u30a2\u30c3\u30d7\u304c\u3042\u308a\u307e\u305b\u3093\u3002",B.i,"\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ud074\ub77c\uc6b0\ub4dc \ubc31\uc5c5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.",B.h,"\u6ca1\u6709\u53ef\u7528\u7684\u4e91\u7aef\u5907\u4efd\u3002",B.k,"Kein Cloud-Backup verf\xfcgbar."],t.N)
B.adI=new A.t([B.m,"Account diverso su questo dispositivo. Scegli i progressi locali o cloud.",B.l,"Hay otra cuenta en este dispositivo. Elige el progreso local o en la nube.",B.j,"\u3053\u306e\u7aef\u672b\u3067\u306f\u5225\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u304c\u4f7f\u308f\u308c\u3066\u3044\u307e\u3059\u3002\u4fdd\u6301\u3059\u308b\u9032\u884c\u72b6\u6cc1\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\uc774 \uae30\uae30\uc5d0 \ub2e4\ub978 \uacc4\uc815\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc720\uc9c0\ud560 \uc9c4\ud589 \uc0c1\ud669\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.h,"\u6b64\u8bbe\u5907\u4e0a\u6709\u5176\u4ed6\u8d26\u6237\u3002\u8bf7\u9009\u62e9\u8981\u4fdd\u7559\u7684\u8fdb\u5ea6\u3002",B.k,"Anderes Konto auf diesem Ger\xe4t. Lokalen oder Cloud-Fortschritt w\xe4hlen."],t.N)
B.ad2=new A.t([B.m,"Nessun salvataggio cloud per questo account. Controlla prima di importare il dispositivo.",B.l,"No hay partida en la nube para esta cuenta. Rev\xedsala antes de importar este dispositivo.",B.j,"\u3053\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u306b\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u304c\u3042\u308a\u307e\u305b\u3093\u3002\u7aef\u672b\u3092\u53d6\u308a\u8fbc\u3080\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\uc774 \uacc4\uc815\uc5d0 \ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \uae30\uae30\ub97c \uac00\uc838\uc624\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.h,"\u6b64\u8d26\u6237\u6ca1\u6709\u4e91\u7aef\u5b58\u6863\u3002\u5bfc\u5165\u6b64\u8bbe\u5907\u524d\u8bf7\u68c0\u67e5\u3002",B.k,"Kein Cloud-Spielstand f\xfcr dieses Konto. Vor dem Import pr\xfcfen."],t.N)
B.ad7=new A.t([B.m,"Trovati progressi cloud pi\xf9 recenti. Controlla prima di sostituire quelli del dispositivo.",B.l,"Se encontr\xf3 progreso m\xe1s reciente en la nube. Rev\xedsalo antes de reemplazar el del dispositivo.",B.j,"\u3088\u308a\u65b0\u3057\u3044\u30af\u30e9\u30a6\u30c9\u9032\u884c\u72b6\u6cc1\u304c\u898b\u3064\u304b\u308a\u307e\u3057\u305f\u3002\u7f6e\u304d\u63db\u3048\u308b\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\ub354 \ucd5c\uc2e0 \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc744 \ucc3e\uc558\uc2b5\ub2c8\ub2e4. \uad50\uccb4\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.h,"\u53d1\u73b0\u66f4\u65b0\u7684\u4e91\u7aef\u8fdb\u5ea6\u3002\u66ff\u6362\u524d\u8bf7\u68c0\u67e5\u3002",B.k,"Neuerer Cloud-Fortschritt gefunden. Vor dem Ersetzen pr\xfcfen."],t.N)
B.aaI=new A.t([B.m,"I progressi locali e cloud sono diversi. Scegli quali mantenere.",B.l,"El progreso local y el de la nube difieren. Elige cu\xe1l conservar.",B.j,"\u30ed\u30fc\u30ab\u30eb\u3068\u30af\u30e9\u30a6\u30c9\u306e\u9032\u884c\u72b6\u6cc1\u304c\u7570\u306a\u308a\u307e\u3059\u3002\u4fdd\u6301\u3059\u308b\u30c7\u30fc\u30bf\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\ub85c\uceec\uacfc \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc720\uc9c0\ud560 \ub370\uc774\ud130\ub97c \uc120\ud0dd\ud558\uc138\uc694.",B.h,"\u672c\u5730\u4e0e\u4e91\u7aef\u8fdb\u5ea6\u4e0d\u540c\u3002\u8bf7\u9009\u62e9\u8981\u4fdd\u7559\u7684\u6570\u636e\u3002",B.k,"Lokaler und Cloud-Fortschritt unterscheiden sich. Zu behaltenden Stand w\xe4hlen."],t.N)
B.aaN=new A.t([B.m,"I progressi cloud sono cambiati su un altro dispositivo. Controlla i salvataggi prima di continuare.",B.l,"El progreso en la nube cambi\xf3 en otro dispositivo. Revisa las partidas antes de continuar.",B.j,"\u5225\u306e\u7aef\u672b\u3067\u30af\u30e9\u30a6\u30c9\u9032\u884c\u72b6\u6cc1\u304c\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\u3002\u7d9a\u884c\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.i,"\ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uacc4\uc18d\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.h,"\u4e91\u7aef\u8fdb\u5ea6\u5df2\u5728\u5176\u4ed6\u8bbe\u5907\u66f4\u6539\u3002\u7ee7\u7eed\u524d\u8bf7\u68c0\u67e5\u5b58\u6863\u3002",B.k,"Cloud-Fortschritt wurde auf einem anderen Ger\xe4t ge\xe4ndert. Spielst\xe4nde pr\xfcfen."],t.N)
